  result = convert(usdCents, 'USD'); // Convert USD to... wait, convert always expects EUR input
  // So this doesn't work. Let's just verify the forward conversion chain
  assert.equal(usdCents, 10850);

  // Convert EUR to GBP
  result = convert(cents, 'GBP');
  assert.equal(result.ok, true);
  assert.equal(result.value, 8425); // 10000 * 0.8425 = 8425
});

test('convert invoice total EUR to USD', () => {
  // Invoice total: €514.25 (51425 cents)
  const result = convert(51425, 'USD');
  assert.equal(result.ok, true);
  // 51425 * 1.085 = 55796.125 → 55796
  assert.equal(result.value, 55796);

  // Format it
  const formatted = formatMoney(result.value, 'USD');
  assert.equal(formatted, '$557.96');
});

test('convert invoice total EUR to GBP', () => {
  // Invoice total: €514.25 (51425 cents)
  const result = convert(51425, 'GBP');
  assert.equal(result.ok, true);
  // 51425 * 0.8425 = 43324.5625 → 43325
  assert.equal(result.value, 43325);

  // Format it
