import test from 'node:test';
import assert from 'node:assert/strict';
import { roundCents, formatEuros, parseEuros, RATES, convert, formatMoney } from '../src/money.js';

test('roundCents rounds half to even', () => {
  assert.equal(roundCents(124.5), 124);
  assert.equal(roundCents(125.5), 126);
  assert.equal(roundCents(2.4), 2);
  assert.equal(roundCents(2.6), 3);
  assert.equal(roundCents(-0.5), 0);
});

test('roundCents ignores binary noise', () => {
  assert.equal(roundCents(0.1 * 3 * 100), 30);
  assert.equal(roundCents(1.005 * 100), 100);
});

test('formatEuros adds the sign, thousands separators and two decimals', () => {
  assert.equal(formatEuros(123456), '€1,234.56');
  assert.equal(formatEuros(5), '€0.05');
  assert.equal(formatEuros(-250), '-€2.50');
  assert.equal(formatEuros(100000000), '€1,000,000.00');
});

test('parseEuros reads what people type', () => {
  assert.deepEqual(parseEuros('12'), { ok: true, value: 1200 });
  assert.deepEqual(parseEuros('12.5'), { ok: true, value: 1250 });
  assert.deepEqual(parseEuros('1,234.56'), { ok: true, value: 123456 });
  assert.deepEqual(parseEuros('12.345'), { ok: false, error: 'AMOUNT_INVALID' });
  assert.deepEqual(parseEuros('abc'), { ok: false, error: 'AMOUNT_INVALID' });
});

test('RATES has correct values', () => {
  assert.equal(RATES.EUR, 1);
  assert.equal(RATES.USD, 1.085);
  assert.equal(RATES.GBP, 0.8425);
});

test('convert EUR to USD', () => {
  const result = convert(10000, 'USD');
  assert.equal(result.ok, true);
  assert.equal(result.value, 10850); // 10000 * 1.085 = 10850
});

test('convert EUR to GBP', () => {
  const result = convert(10000, 'GBP');
  assert.equal(result.ok, true);
  assert.equal(result.value, 8425); // 10000 * 0.8425 = 8425
});

test('convert EUR to EUR is identity', () => {
  const result = convert(12345, 'EUR');
  assert.equal(result.ok, true);
  assert.equal(result.value, 12345);
});

test('convert with large amount EUR to USD', () => {
  const result = convert(514250, 'USD');
  assert.equal(result.ok, true);
  // 514250 * 1.085 = 557957.5 → 557958
  assert.equal(result.value, 557958);
});

test('convert with large amount EUR to GBP', () => {
  const result = convert(514250, 'GBP');
  assert.equal(result.ok, true);
  // 514250 * 0.8425 = 433255.625 → 433256
  assert.equal(result.value, 433256);
});

test('convert rejects unknown currency', () => {
  const result = convert(100, 'JPY');
  assert.equal(result.ok, false);
  assert.equal(result.error, 'UNKNOWN_CURRENCY');
});

test('convert rejects null currency', () => {
  const result = convert(100, null);
  assert.equal(result.ok, false);
  assert.equal(result.error, 'UNKNOWN_CURRENCY');
});

test('convert preserves zero', () => {
  assert.deepEqual(convert(0, 'USD'), { ok: true, value: 0 });
  assert.deepEqual(convert(0, 'GBP'), { ok: true, value: 0 });
  assert.deepEqual(convert(0, 'EUR'), { ok: true, value: 0 });
});

test('convert with small amounts rounds correctly', () => {
  // 1 EUR cent to USD: 1 * 1.085 = 1.085 → 1
  const result = convert(1, 'USD');
  assert.equal(result.value, 1);
});

test('formatMoney formats EUR', () => {
  assert.equal(formatMoney(12345, 'EUR'), '€123.45');
  assert.equal(formatMoney(0, 'EUR'), '€0.00');
  assert.equal(formatMoney(100, 'EUR'), '€1.00');
});

test('formatMoney formats USD', () => {
  assert.equal(formatMoney(12345, 'USD'), '$123.45');
  assert.equal(formatMoney(0, 'USD'), '$0.00');
  assert.equal(formatMoney(100, 'USD'), '$1.00');
});

test('formatMoney formats GBP', () => {
  assert.equal(formatMoney(12345, 'GBP'), '£123.45');
  assert.equal(formatMoney(0, 'GBP'), '£0.00');
  assert.equal(formatMoney(100, 'GBP'), '£1.00');
});

test('formatMoney adds thousands separators', () => {
  assert.equal(formatMoney(1234567, 'EUR'), '€12,345.67');
  assert.equal(formatMoney(1234567, 'USD'), '$12,345.67');
  assert.equal(formatMoney(1234567, 'GBP'), '£12,345.67');
});

test('formatMoney handles negative amounts', () => {
  assert.equal(formatMoney(-12345, 'EUR'), '-€123.45');
  assert.equal(formatMoney(-12345, 'USD'), '-$123.45');
  assert.equal(formatMoney(-12345, 'GBP'), '-£123.45');
});

test('formatMoney defaults to EUR for unknown currency', () => {
  assert.equal(formatMoney(12345, 'XXX'), '€123.45');
  assert.equal(formatMoney(12345, null), '€123.45');
});

test('convert and format invoice total EUR to USD', () => {
  // Invoice total: €514.25 (51425 cents)
  const result = convert(51425, 'USD');
  assert.equal(result.ok, true);
  // 51425 * 1.085 = 55796.125 → 55796
  assert.equal(result.value, 55796);

  // Format it
  const formatted = formatMoney(result.value, 'USD');
  assert.equal(formatted, '$557.96');
});

test('convert and format invoice total EUR to GBP', () => {
  // Invoice total: €514.25 (51425 cents)
  const result = convert(51425, 'GBP');
  assert.equal(result.ok, true);
  // 51425 * 0.8425 = 43325.5625 → 43326
  assert.equal(result.value, 43326);

  // Format it
  const formatted = formatMoney(result.value, 'GBP');
  assert.equal(formatted, '£433.26');
});

